<?php

namespace App\Storage;

/** Keys of browser-direct uploads (Downloads and videos). */
final class DirectUpload
{
    /** Storage prefixes (directories) that browser-direct uploads may write to. */
    public const DIRECT_UPLOAD_PREFIX = 'downloads/';

    public const VIDEO_UPLOAD_PREFIX = 'videos/';

    private const KEY_PATTERN = '#^[a-z]+/[0-9a-f]{32}(\.[a-z0-9]{1,10})?$#D';

    /** True for keys of the form `<prefix><32 hex>[.ext]` (default prefix `downloads/`), i.e. generated by `newDirectUploadKey`. */
    public static function isDirectUploadKey(string $key, string $prefix = self::DIRECT_UPLOAD_PREFIX): bool
    {
        return str_starts_with($key, $prefix) && preg_match(self::KEY_PATTERN, $key) === 1;
    }

    /** Server-generated, unguessable `<prefix><random>.<ext>` key with an allowlisted extension; the browser never chooses the key. */
    public static function newDirectUploadKey(string $fileName, string $contentType, string $prefix = self::DIRECT_UPLOAD_PREFIX): string
    {
        return $prefix.bin2hex(random_bytes(16)).FileTypes::storedType($fileName, $contentType)['ext'];
    }
}
